# --- 잡으면 지워진다 ---

$ cat FlagCleared.java | grep -A7 'Thread t'
Thread t = new Thread(() -> {
    try { Thread.sleep(10000); }
    catch (InterruptedException e) {
        log.info("catch 안: 플래그 {}", Thread.currentThread().isInterrupted());
    }
    log.info("catch 밖: 플래그 {}", Thread.currentThread().isInterrupted());
}, "w-0");

