#   grep 두 줄로 찾는다


# --- 검사로 만든다 ---

$ cat check-interrupt.sh
#!/bin/sh
# InterruptedException 을 잡고 복원도 되던지지도 않는 자리를 찾는다
grep -rn -A4 'catch (InterruptedException' src/main/java/ \
 | awk '/catch \(InterruptedException/ {file=$0; buf=""; next}
        /^--/ {if (buf !~ /interrupt\(\)|throw/) print file; buf=""; next}
        {buf = buf $0}'

$ ./check-interrupt.sh
src/main/java/study/th/Poller.java:41:      } catch (InterruptedException e) {
src/main/java/study/th/Batch.java:88:       } catch (InterruptedException e) {

